actions.script:
import org.moqui.context.ExecutionContext
import org.moqui.impl.context.UserFacadeImpl.UserInfo

ExecutionContext ec = context.ec

// Permissions are handled by Moqui's artifact authorization system
// Users must be in appropriate MCP_* groups with access to the MCP artifact groups

ec.logger.info("MCP Initialize for session ${sessionId}, user ${ec.user.userId}")

// Validate protocol version - support common MCP versions with version negotiation
List<String> supportedVersions = ["2025-11-25", "2025-06-18", "2025-03-26", "2024-11-05", "2024-10-07", "2023-06-05"]
if (!supportedVersions.contains(protocolVersion)) {
    throw new Exception("Unsupported protocol version: ${protocolVersion}. Supported versions: ${supportedVersions.join(', ')}")
}

// Get current user context (if authenticated)
String userId = ec.user.userId
String userAccountId = userId ? userId : null

// Try to load root instructions from wiki
String instructions = null
try {
    EntityValue wikiPage = ec.entity.find("moqui.resource.wiki.WikiPage")
        .condition("wikiSpaceId", "MCP_AGENT_DOCS")
        .condition("pagePath", "root")
        .useCache(true)
        .one()

    if (wikiPage) {
        EntityValue wikiSpace = ec.entity.find("moqui.resource.wiki.WikiSpace")
            .condition("wikiSpaceId", wikiPage.wikiSpaceId)
            .one()

        if (wikiSpace) {
            String pageLocation = wikiSpace.rootPageLocation
            if (!pageLocation.endsWith('/')) pageLocation += '/'
            pageLocation += wikiPage.pagePath + '.md'

            String pageRef = ec.resource.getLocationReference(pageLocation)
            String wikiText = pageRef?.getText()
            if (wikiText) {
                instructions = wikiText
                ec.logger.info("MCP Initialize: Loaded root instructions from wiki")
            }
        }
    }
} catch (Exception e) {
    ec.logger.debug("Could not load root instructions from wiki: ${e.message}")
}

// Fallback to hardcoded instructions if wiki not available
if (!instructions) {
    instructions = "This server provides access to Moqui ERP through MCP. For create, update, assign, close, confirm, submit, delete, or other state-changing user requests, do not answer from general knowledge and do not only describe what you would do. You must call a Moqui tool. On the algebraic runtime path, first use moqui_plan_prompt_as_morphism. When needed, inspect candidates with moqui_search_morphisms and moqui_get_morphism_signature, derive transitive effects with moqui_derive_effective_service_effects, and inspect object schemas with moqui_search_objects and moqui_get_object_schema. For natural-language user intents that require registered Moqui skills, search authorized AgentSkills with moqui_search_agent_skills and load the selected skill with moqui_get_agent_skill. Prefer skill-first planning and algebraic morphism planning over legacy prompt-document search. Use moqui_resolve_agent_skill when you want a single best skill candidate. Treat moqui_search_agent_prompts → moqui_get_agent_document → moqui_execute_agent_prompt as a legacy fallback path only, for already-known prompt documents or temporary compatibility while the algebraic catalog is still being completed. If you execute a root create document directly for a composite request, include queryText so Moqui can decompose the aggregate. Use moqui_get_runtime_context and moqui_get_session_context to ground follow-up prompts. Do not bypass Moqui artifact authorization. Use moqui_check_artifact_access to verify access before mutating operations."
}

// Build server capabilities - don't fetch actual tools/resources during init
// Tools and resources will be discovered via separate list requests per MCP spec
Map<String, Object> serverCapabilities = [
    tools: [listChanged: true],
    resources: [subscribe: true, listChanged: true],
    logging: [:]
]

// Build server info with useful metadata
String moquiVersion = ec.factory.moquiVersion ?: "Unknown"
String runtimePath = ec.factory.runtimePath ?: "Unknown"

Set<String> userGroupIdSet = (ec.user.userGroupIdSet ?: []) as Set
boolean isPrivileged = userGroupIdSet.contains('ADMIN') || userGroupIdSet.contains('MCP_DEBUG')

Map<String, Object> serverInfo = [
    name: "Moqui MCP Server",
    version: "2.0.2",
    moquiVersion: moquiVersion,
    currentUser: ec.user?.username,
    currentUserId: ec.user?.userId
]
if (isPrivileged) {
    serverInfo.hostname = System.getenv("HOSTNAME") ?: System.getProperty("hostname", "Unknown")
    serverInfo.javaVersion = System.getProperty("java.version") ?: "Unknown"
    serverInfo.javaVendor = System.getProperty("java.vendor") ?: "Unknown"
    serverInfo.runtimePath = runtimePath
    try {
        serverInfo.serverStartTime = java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime()
    } catch (Exception ignored) {}
}

Map runtimeConfig = ec.service.sync().name('org.moqui.harness.AgentFacadeServices.check#RuntimeConfiguration').parameters([
    checkIndexes: false
]).call()

result = [
    protocolVersion: protocolVersion,
    capabilities: serverCapabilities,
    serverInfo: serverInfo,
    sessionId: sessionId,
    instructions: instructions,
    runtimeConfiguration: [
        status: runtimeConfig.status,
        warnings: runtimeConfig.warnings,
        details: runtimeConfig.details
    ]
]

ec.logger.info("MCP Initialize for user ${userId} (session ${sessionId}): capabilities negotiated")

import groovy.json.JsonBuilder
import groovy.json.JsonSlurper
ec.message.clearAll()
Set<String> userGroupIdSet = (ec.user.userGroupIdSet ?: []) as Set
boolean isDebugUser = userGroupIdSet.contains('MCP_DEBUG') || userGroupIdSet.contains('ADMIN')
Map<String, String> toolMappings = [
    "moqui_search_artifacts" : "org.moqui.harness.AgentFacadeServices.search#Artifacts",
    "moqui_get_artifact" : "org.moqui.harness.AgentFacadeServices.get#Artifact",
    "moqui_search_all"   : "org.moqui.harness.AgentFacadeServices.search#AllDocuments",
    "moqui_call_service_guarded": "org.moqui.harness.AgentFacadeServices.call#ServiceGuarded",
    "moqui_discover_artifacts"   : "org.moqui.harness.AgentFacadeServices.discover#AndIndexArtifacts",
    "moqui_discovery_status"     : "org.moqui.harness.AgentFacadeServices.get#DiscoveryStatus"
]
Map<String, Map> providerToolMappings = [:]
def jsonSlurper = new JsonSlurper()
ec.entity.find('moqui.service.ServiceRegister').condition('serviceTypeEnumId', 'McpToolProvider').useCache(true).list()?.each { providerReg ->
    try {
        Map cfg = [:]
        if (providerReg.configParameters) cfg = (Map) jsonSlurper.parseText(providerReg.configParameters)
        String listServiceName = providerReg.serviceName
        String callServiceName = cfg.callServiceName ?: providerReg.serviceName
        Map providerRes = ec.service.sync().name(listServiceName).parameters(sessionId ? [sessionId: sessionId] : [:]).call()
        List providerTools = (providerRes?.toolList ?: providerRes?.tools ?: []) as List
        providerTools.each { Map toolDef ->
            if (toolDef?.name) providerToolMappings[toolDef.name as String] = [callServiceName: callServiceName, providerId: providerReg.serviceRegisterId]
        }
    } catch (Throwable t) {
        ec.logger.warn("Unable to load MCP tool provider ${providerReg.serviceRegisterId}: ${t.message}")
    }
}
Set debugToolNames = ['moqui_search_artifacts', 'moqui_get_artifact', 'moqui_search_all', 'moqui_call_service_guarded',
                      'moqui_discover_artifacts', 'moqui_discovery_status', 'moqui_refresh_agent_skills', 'moqui_index_agent_skills'] as Set
try {
    String svc = toolMappings[name]
    Map providerEntry = providerToolMappings[name]
    if (debugToolNames.contains(name) && !isDebugUser) {
        result = [content: [[type: "text", text: "Tool not available for current user: ${name}"]], isError: true]
        return
    }
    if (!svc && providerEntry?.callServiceName) {
        Map<String, Object> providerCallParameters = [toolName: name]
        if (arguments instanceof Map) providerCallParameters.arguments = arguments
        if (sessionId) providerCallParameters.sessionId = sessionId
        Map providerResult = ec.service.sync().name(providerEntry.callServiceName as String).requireNewTransaction(true).parameters(providerCallParameters).call()
        if (ec.message.hasError()) {
            String errText = ec.message.errorsString
            ec.message.clearErrors()
            result = [content: [[type: "text", text: "Error: ${errText}"]], isError: true]
            return
        }
        Map<String, Object> actualProviderResult = providerResult?.result ?: providerResult
        result = (actualProviderResult instanceof Map && actualProviderResult.content instanceof List) ? actualProviderResult :
            [content: [[type: "text", text: new JsonBuilder(actualProviderResult).toString()]], isError: false]
        return
    }
    if (!svc) throw new Exception("Unknown tool: ${name}. Available: ${(toolMappings.keySet() + providerToolMappings.keySet()).sort().join(', ')}")
    Map<String, Object> toolParameters = [:]
    if (arguments instanceof Map) toolParameters.putAll(arguments)
    if (sessionId && !toolParameters.sessionId) toolParameters.sessionId = sessionId
    if (name == 'moqui_call_service_guarded') {
        if (!toolParameters.toolName) toolParameters.toolName = name
        if (!toolParameters.containsKey('directToolCall')) toolParameters.directToolCall = true
    }
    Map<String, Object> res = ec.service.sync().name(svc).requireNewTransaction(true).parameters(toolParameters).call()
    if (ec.message.hasError()) {
        String errText = ec.message.errorsString
        ec.message.clearErrors()
        result = [content: [[type: "text", text: "Error: ${errText}"]], isError: true]
        return
    }
    Map<String, Object> actual = res?.result ?: res
    result = (actual instanceof Map && actual.content instanceof List) ? actual :
        [content: [[type: "text", text: new JsonBuilder(actual).toString()]], isError: false]
} catch (Exception e) {
    result = [content: [[type: "text", text: "Error: ${e.message}"]], isError: true]
    ec.logger.error("MCP tool error", e)
}

// Get current user information
String currentUser = ec.user.username
String currentUserId = ec.user.userId

// Try to get visit information if sessionId is provided
Map<String, Object> visitInfo = null
if (sessionId) {
    try {
        Map<String, Object> visit = ec.entity.find("moqui.server.Visit")
            .condition("visitId", sessionId)
            .one()

        if (visit) {
            visitInfo = [
                visitId: visit.visitId,
                userId: visit.userId,
                fromDate: visit.fromDate,
                lastUpdatedStamp: visit.lastUpdatedStamp
            ]
        }
    } catch (Exception e) {
        ec.logger.warn("Error getting visit info for sessionId ${sessionId}: ${e.message}")
    }
}

result = [
    timestamp: ec.user.getNowTimestamp(),
    status: "healthy",
    version: "2.0.2",
    sessionId: sessionId,
    currentUser: currentUser,
    currentUserId: currentUserId,
    visitInfo: visitInfo,
    architecture: "Visit-based sessions"
]
Map<String, Object> runtimeConfig = ec.service.sync().name('org.moqui.harness.AgentFacadeServices.check#RuntimeConfiguration').parameters([
    checkIndexes: true
]).call()
result.runtimeConfiguration = [
    status: runtimeConfig.status,
    errors: runtimeConfig.errors,
    warnings: runtimeConfig.warnings,
    details: runtimeConfig.details
]
if (runtimeConfig.status == 'error') result.status = 'degraded'
else if (runtimeConfig.status == 'warn') result.status = 'healthy_with_warnings'
